    if D + L != X * Y:
        print(0)
        return

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        k = min(k, n - k)
        num = 1
        for i in range(k):
            num = num * (n - i) % MOD
        den = 1
        for i in range(1, k + 1):
